<?php
if($user['role']!=='Administrator'){http_response_code(403);echo '<div class="alert alert-error">Only the school administrator can review the audit log.</div>';return;}
$pdo=db();$dateOk=static function(string $v):bool{if($v==='')return true;$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);$e=DateTimeImmutable::getLastErrors();return preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)===1&&$d!==false&&$d->format('Y-m-d')===$v&&($e===false||(!$e['warning_count']&&!$e['error_count']));};$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$actor=filter_var($_GET['actor']??null,FILTER_VALIDATE_INT);$action=trim((string)($_GET['action']??''));$entity=trim((string)($_GET['entity']??''));$validFilter=$dateOk($from)&&$dateOk($to)&&(!$from||!$to||$from<=$to)&&$actor!==false&&strlen($action)<=80&&strlen($entity)<=80;if(!$validFilter){$from='';$to='';$actor=null;$action='';$entity='';}$where=[];$params=[];if($from!==''){$where[]='a.created_at>=:from_date';$params['from_date']=$from.' 00:00:00';}if($to!==''){$where[]='a.created_at<:to_date';$params['to_date']=(new DateTimeImmutable($to))->modify('+1 day')->format('Y-m-d').' 00:00:00';}if($actor){$where[]='a.user_id=:actor';$params['actor']=$actor;}if($action!==''){$where[]='a.action LIKE :action';$params['action']='%'.$action.'%';}if($entity!==''){$where[]='a.entity_type LIKE :entity';$params['entity']='%'.$entity.'%';}$filterSql=$where?' WHERE '.implode(' AND ',$where):'';$page=filter_var($_GET['p']??1,FILTER_VALIDATE_INT);if(!$page||$page<1)$page=1;$countQ=$pdo->prepare('SELECT COUNT(*) FROM audit_logs a'.$filterSql);$countQ->execute($params);$total=(int)$countQ->fetchColumn();$perPage=50;$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;$q=$pdo->prepare('SELECT a.id,a.user_id,a.action,a.entity_type,a.entity_id,a.details,a.ip_address,a.created_at,u.full_name,u.email FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id'.$filterSql.' ORDER BY a.created_at DESC,a.id DESC LIMIT '.$perPage.' OFFSET '.$offset);$q->execute($params);$rows=$q->fetchAll();$actors=$pdo->query('SELECT DISTINCT u.id,u.full_name FROM audit_logs a JOIN users u ON u.id=a.user_id ORDER BY u.full_name')->fetchAll();
?>
<div class="page-heading"><div><div class="eyebrow">ACCOUNTABILITY · ADMINISTRATOR ONLY</div><h1>Audit log</h1><p class="subheading">Review recorded sign-ins and school record changes. Details are retained for accountability.</p></div></div>
<section class="panel settings-panel"><form method="get" class="compact-form"><input type="hidden" name="page" value="audit"><label>From<input type="date" name="from" value="<?= h($from) ?>"></label><label>To<input type="date" name="to" value="<?= h($to) ?>"></label><label>Actor<select name="actor"><option value="">All actors</option><?php foreach($actors as $person): ?><option value="<?= (int)$person['id'] ?>" <?= (int)$actor===(int)$person['id']?'selected':'' ?>><?= h($person['full_name']) ?></option><?php endforeach; ?></select></label><label>Action contains<input name="action" maxlength="80" value="<?= h($action) ?>" placeholder="e.g. fees."></label><label>Record type contains<input name="entity" maxlength="80" value="<?= h($entity) ?>" placeholder="e.g. students"></label><button class="primary-button">Filter log</button><a class="text-button" href="?page=audit">Clear filters</a></form></section>
<section class="panel learners-panel"><div class="panel-heading"><div><h2><?= number_format($total) ?> audit event<?= $total===1?'':'s' ?></h2><p>Showing <?= $total?number_format($offset+1).'–'.number_format(min($offset+$perPage,$total)):'0' ?> · page <?= (int)$page ?> of <?= (int)$pages ?></p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Date / time</th><th>Actor</th><th>Event</th><th>Record</th><th>Network</th><th>Details</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= h(date('d M Y H:i:s',strtotime($row['created_at']))) ?></td><td><?= h($row['full_name']??'Deleted account') ?><?php if($row['email']): ?><small class="muted-cell"><?= h($row['email']) ?></small><?php endif; ?></td><td><code><?= h($row['action']) ?></code></td><td><?= h($row['entity_type']?:'—') ?><?= $row['entity_id']?'<small class="muted-cell">#'.(int)$row['entity_id'].'</small>':'' ?></td><td><?= $row['ip_address']?'••••••':'—' ?></td><td><?php if($row['details']): ?><details><summary>View details</summary><pre class="audit-details"><?= h(json_encode(json_decode((string)$row['details'],true)??(string)$row['details'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)) ?></pre></details><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="6" class="empty-cell">No audit events match these filters.</td></tr><?php endif; ?></tbody></table></div><?php if($pages>1): ?><div class="form-actions"><?php if($page>1): ?><a class="outline-button" href="?<?= h(http_build_query(array_merge($_GET,['p'=>$page-1]))) ?>">← Newer</a><?php endif; ?><?php if($page<$pages): ?><a class="outline-button" href="?<?= h(http_build_query(array_merge($_GET,['p'=>$page+1]))) ?>">Older →</a><?php endif; ?></div><?php endif; ?></section>
